import type { OrderItemModel } from '@/order/data/models';

type FreeGiftLineItem = Pick<
  OrderItemModel,
  'price' | 'regularPrice' | 'totalQuantity' | 'itemPrices'
>;

function getCatalogOriginalPrice(item: FreeGiftLineItem): {
  value: number;
  currency: string;
} {
  const fromRegular = item.regularPrice?.value ?? 0;
  if (fromRegular > 0) {
    return {
      value: fromRegular,
      currency: item.regularPrice?.currency ?? item.price?.currency ?? 'USD',
    };
  }

  const fromOrderOriginal = item.itemPrices?.originalPrice?.value ?? 0;
  if (fromOrderOriginal > 0) {
    return {
      value: fromOrderOriginal,
      currency:
        item.itemPrices?.originalPrice?.currency ??
        item.price?.currency ??
        'USD',
    };
  }

  return {
    value: 0,
    currency: item.price?.currency ?? item.regularPrice?.currency ?? 'USD',
  };
}

/**
 * Unit amount shown for free-gift lines: line price when set (e.g. catalog special),
 * otherwise catalog original / regularPrice.
 */
export function getFreeGiftDisplayUnit(item: FreeGiftLineItem): {
  value: number;
  currency: string;
} {
  const lineUnit = item.price?.value ?? 0;
  if (lineUnit > 0) {
    return {
      value: lineUnit,
      currency: item.price?.currency ?? item.regularPrice?.currency ?? 'USD',
    };
  }

  return getCatalogOriginalPrice(item);
}

/** Row strike total for free-gift lines (display unit × quantity). */
export function getFreeGiftLineStrikeTotal(item: FreeGiftLineItem): {
  value: number;
  currency: string;
} {
  const unit = getFreeGiftDisplayUnit(item);
  const qty = item.totalQuantity ?? 1;
  return {
    value: unit.value * qty,
    currency: unit.currency,
  };
}
